for (const [id, forms] of Object.entries({"basics":["Subjektfrage ohne do: Who teaches this class? Objektfrage mit do: What does she teach?","Question tags: positiver Hauptsatz → negativer Anhang (You play, don’t you?); negativer Hauptsatz → positiver Anhang (You don’t play, do you?).","Häufigkeitsadverbien: She often reads, aber She is often late."],"tenses":["Zustandsverben stehen in ihrer Zustandsbedeutung meist nicht im progressive: I know the answer. The soup tastes good."],"future":["Auch nach as soon as, until und before steht in zukünftigen Zeitsätzen meist simple present: I’ll wait until she arrives.","Fahrpläne und feste Programme können im simple present stehen: The train leaves tomorrow at seven."],"conditionals":["Typ 0 (allgemeine Regeln): if + simple present → simple present. If you heat ice, it melts.","Unless bedeutet in Bedingungen häufig if ... not: Unless you hurry = If you do not hurry."],"reported":["Aufforderung: She asked me to wait. Verneint: She told me not to leave.","Indirekte Ja-/Nein-Frage: He asked if/whether I was ready. Kein Fragewortwechsel der Satzstellung.","Bei neuer Zeitperspektive: tomorrow → the next/following day; yesterday → the day before; now → then."],"passive":["Futur-Passiv: will be + past participle. The result will be announced.","Present progressive passive: am/is/are being + past participle. The room is being painted."],"ing":["encourage someone to do something; prevent someone from doing something."],"comparison":["Nach linking verbs wie look, feel, smell und taste beschreibt ein Adjektiv das Subjekt: The room looks bright. The soup tastes good."],"quantifiers":["Unzählbares mit Einheiten: two pieces of information, three pieces of advice.","Bei Angeboten ist some üblich: Would you like some tea? All of them umfasst eine Gruppe; every braucht normalerweise ein Nomen im Singular."],"relatives":["Im defining relative clause kann ein Objektpronomen wegfallen: the book (that) I read. Ein Subjektpronomen bleibt: the book that fell.","Whose kann auch auf Dinge verweisen: a website whose exercises are free. Where verweist auf einen Ort: the town where I live."],"possessive":["Weitere Verbformen: draw – drew – drawn; ride – rode – ridden; catch – caught – caught."]})) { window.LAB_DATA.grammar.find(t=>t.id===id).forms.push(...forms); }
